function isObj(v) {
  return !!v && typeof v === "object" && !Array.isArray(v);
}

function uid() {
  try {
    if (typeof crypto !== "undefined" && crypto?.randomUUID)
      return crypto.randomUUID();
  } catch (_) {}
  return `id_${Math.random().toString(16).slice(2)}_${Date.now().toString(16)}`;
}

function themeDefaults(theme) {
  const t = String(theme || "default");
  if (t === "dark") {
    return {
      bg: "rgba(255,255,255,0.04)",
      border: "rgba(255,255,255,0.10)",
      text: "#ffffff",
    };
  }
  if (t === "purple") {
    return {
      bg: "rgba(124,58,237,0.12)",
      border: "rgba(124,58,237,0.25)",
      text: "#ffffff",
    };
  }
  if (t === "blue") {
    return {
      bg: "rgba(59,130,246,0.10)",
      border: "rgba(59,130,246,0.22)",
      text: "#ffffff",
    };
  }
  if (t === "light") {
    return {
      bg: "rgba(255,255,255,0.92)",
      border: "rgba(0,0,0,0.10)",
      text: "#0b0d12",
    };
  }
  return {
    bg: "rgba(255,255,255,0.03)",
    border: "rgba(255,255,255,0.08)",
    text: "#ffffff",
  };
}

function shadowCss(v) {
  const s = String(v || "md");
  if (s === "none") return "none";
  if (s === "sm") return "0 6px 18px rgba(0,0,0,0.25)";
  if (s === "lg") return "0 18px 60px rgba(0,0,0,0.45)";
  return "0 10px 30px rgba(0,0,0,0.35)";
}

function deepMergeHomeDefaults(incoming) {
  const src = isObj(incoming) ? incoming : {};
  return {
    ...HOME_DEFAULTS,
    hero: { ...HOME_DEFAULTS.hero, ...(src.hero || {}) },
    join: { ...HOME_DEFAULTS.join, ...(src.join || {}) },
    watch_more: { ...HOME_DEFAULTS.watch_more, ...(src.watch_more || {}) },
    about: { ...HOME_DEFAULTS.about, ...(src.about || {}) },
    extra_sections: Array.isArray(src.extra_sections) ? src.extra_sections : [],
  };
}

function clampNum(n, min, max) {
  const v = Number(n);
  if (Number.isNaN(v)) return min;
  return Math.max(min, Math.min(max, v));
}

function normalizeSpacing(v) {
  const s = String(v ?? "").trim();
  if (!s) return "";
  if (/^\d+(\.\d+)?$/.test(s)) return `${s}px`;
  return s;
}

function defaultSectionStyle(theme = "default") {
  return {
    padding: "",
    margin: "",
    max_width: "",
    bg_color: "",
    text_color: "",
    title_color: "",
    border_color: "",
    border_width: "",
    radius: 14,
    shadow: "soft", // none | soft | strong
    align: "left",
    content_gap: "",
    font_size: "",
    line_height: "",
    show_title: true,
    title_tag: "h3",
    title_size: 22,
    title_weight: 800,
    bg_image_url: "",
    bg_image_fit: "cover",
    bg_image_pos: "center",
    overlay: 0.0,
    overlay_color: "",
    overlay_opacity: "",
    img_radius: 12,
    img_shadow: "none",
  };
}

function ensureSectionShape(s) {
  const sec = isObj(s) ? s : {};
  const layout = String(sec.layout || "card"); // card | full | highlight | two_columns
  const theme = String(sec.theme || "default"); // default | dark | purple | blue | light
  const styles = isObj(sec.styles) ? sec.styles : {};

  const baseStyle = defaultSectionStyle(theme);

  const rawBlocks = Array.isArray(sec.blocks) ? sec.blocks : [];
  const blocks = rawBlocks
    .map((b) => (isObj(b) ? b : {}))
    .map((b) => ({
      id: String(b.id || uid()),
      type: String(b.type || "richtext"),
      ...b,
    }));

  return {
    id: String(sec.id || uid()),
    title: String(sec.title || ""),
    html: String(sec.html || ""),
    layout,
    theme,
    left_html: String(
      sec.left_html || (layout === "two_columns" ? sec.html || "" : ""),
    ),
    right_html: String(sec.right_html || ""),
    blocks,
    styles: {
      ...baseStyle,
      ...styles,
      padding: normalizeSpacing(styles.padding ?? baseStyle.padding),
      margin: normalizeSpacing(styles.margin ?? baseStyle.margin),
      max_width: String(styles.max_width ?? baseStyle.max_width ?? ""),
      border_width: String(styles.border_width ?? baseStyle.border_width ?? ""),
      content_gap: normalizeSpacing(
        styles.content_gap ?? baseStyle.content_gap,
      ),
      font_size: String(styles.font_size ?? baseStyle.font_size ?? ""),
      line_height: String(styles.line_height ?? baseStyle.line_height ?? ""),
      overlay_color: String(
        styles.overlay_color ?? baseStyle.overlay_color ?? "",
      ),
      overlay_opacity: String(
        styles.overlay_opacity ?? baseStyle.overlay_opacity ?? "",
      ),
      radius: clampNum(styles.radius ?? baseStyle.radius, 0, 60),
      title_size: clampNum(styles.title_size ?? baseStyle.title_size, 10, 64),
      title_weight: clampNum(
        styles.title_weight ?? baseStyle.title_weight,
        200,
        900,
      ),
      overlay: Math.max(
        0,
        Math.min(0.9, Number(styles.overlay ?? baseStyle.overlay) || 0),
      ),
      img_radius: clampNum(styles.img_radius ?? baseStyle.img_radius, 0, 60),
    },
  };
}

function safeHtml(html) {
  // minimal guard: ensure string + fix relative /uploads URLs (React runs on :5001)
  const raw = String(html || "");
  const base = (api?.defaults?.baseURL || "").replace(/\/api\/?$/i, "");
  if (!base) return { __html: raw };

  const fixed = raw
    .replace(/(src=\")\/uploads\//g, `$1${base}/uploads/`)
    .replace(/(src=\')\/uploads\//g, `$1${base}/uploads/`)
    .replace(/(href=\")\/uploads\//g, `$1${base}/uploads/`)
    .replace(/(href=\')\/uploads\//g, `$1${base}/uploads/`);

  return { __html: fixed };
}

/* -----------------------------------------
   Public Home content loader (content_json)
----------------------------------------- */
async function fetchHomeContentJson() {
  // Try a few common shapes/endpoints without breaking anything if missing.
  const tries = [
    // ✅ primary for this backend (pagesPublic.js mounted at /api/pages)
    { path: "/pages/home" },

    // legacy / back-compat paths (older builds)
    { path: "/public/pages/home" },
    { path: "/pages/public/home" },
    { path: "/public/pages", params: { slug: "home" } },
    { path: "/public/page", params: { slug: "home" } },
  ];

  for (const t of tries) {
    const r = await safeGet(t.path, { params: t.params });
    if (!r.ok) continue;

    const d = r.data || {};
    const page = d.page || d.data?.page || d.result?.page || null;

    const cj =
      page?.content_json ||
      d?.content_json ||
      d?.page?.content_json ||
      d?.data?.content_json ||
      null;

    if (cj && isObj(cj)) return cj;

    // Sometimes endpoint returns list of pages
    const items = Array.isArray(d.pages)
      ? d.pages
      : Array.isArray(d.items)
        ? d.items
        : null;
    if (Array.isArray(items)) {
      const home = items.find(
        (x) => String(x?.slug || "").toLowerCase() === "home",
      );
      if (home?.content_json && isObj(home.content_json))
        return home.content_json;
    }
  }

  return null;
}

export default function Home() {
  const [homeModel, setHomeModel] = useState(() => deepMergeHomeDefaults(null));
  const [homeLoading, setHomeLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      setHomeLoading(true);
      try {
        const cj = await fetchHomeContentJson();
        if (cancelled) return;

        if (cj && isObj(cj)) {
          setHomeModel(deepMergeHomeDefaults(cj));
        } else {
          // keep defaults
          setHomeModel(deepMergeHomeDefaults(null));
        }
      } finally {
        if (!cancelled) setHomeLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <main className="home-root">
      <HomeSections model={homeModel} loading={homeLoading} />
      <Spacer />
    </main>
  );
}

/* ---------------------------------------------------------
   Home is now builder-driven (Option A)
   We normalize legacy home fields into builder blocks so older data still works.
--------------------------------------------------------- */
function normalizeHomeSections(model) {
  const m = isObj(model) ? model : {};
  const extraRaw = Array.isArray(m.extra_sections) ? m.extra_sections : [];
  const extra = extraRaw.map(ensureSectionShape);

  const hasCore = extra.some((s) =>
    (Array.isArray(s.blocks) ? s.blocks : []).some(
      (b) => String(b?.type || "") === "home_hero",
    ),
  );
  if (hasCore) return extra;

  const hero = m.hero || HOME_DEFAULTS.hero;
  const join = m.join || HOME_DEFAULTS.join;
  const cta = m.watch_more || HOME_DEFAULTS.watch_more;
  const about = m.about || HOME_DEFAULTS.about;

  const core = [
    {
      id: "core-hero",
      title: "Hero",
      layout: "full",
      theme: "default",
      blocks: [
        {
          id: uid(),
          type: "home_hero",
          kicker: hero.kicker || "",
          title: hero.title || "",
          sub: hero.sub || "",
          cta_text: hero.cta_text || "Start Watching",
          cta_href: hero.cta_href || "/catalog",
          background_url: hero.background_url || "",
        },
      ],
    },
    {
      id: "core-join",
      title: "Join Strip",
      layout: "full",
      theme: "default",
      blocks: [
        {
          id: uid(),
          type: "home_join",
          eyebrow: join.eyebrow || "",
          title: join.title || "",
          sub: join.sub || "",
          cta_text: join.cta_text || "Join Now",
          cta_href: join.cta_href || "/signup",
        },
      ],
    },
    {
      id: "core-featured-live",
      title: "Featured Live Highlight",
      layout: "full",
      theme: "default",
      blocks: [{ id: uid(), type: "featured_live", show: true }],
    },
    {
      id: "core-latest-teaching",
      title: "Latest Teaching",
      layout: "full",
      theme: "default",
      blocks: [{ id: uid(), type: "latest_teaching", show: true }],
    },
    {
      id: "core-cta",
      title: "Watch More CTA",
      layout: "full",
      theme: "default",
      blocks: [
        {
          id: uid(),
          type: "home_cta",
          title: cta.title || "",
          sub: cta.sub || "",
          cta_text: cta.cta_text || "Browse Catalog",
          cta_href: cta.cta_href || "/catalog",
        },
      ],
    },
    {
      id: "core-about",
      title: "About Section",
      layout: "full",
      theme: "default",
      blocks: [
        {
          id: uid(),
          type: "home_about",
          name: about.name || "",
          text: about.text || "",
          avatar_url: about.avatar_url || "",
        },
      ],
    },
  ].map(ensureSectionShape);

  return [...core, ...extra];
}

function HomeSections({ model, loading }) {
  const sections = useMemo(() => normalizeHomeSections(model), [model]);

  if (!sections.length) return null;

  return (
    <>
      {sections.map((sec) => {
        const blocks = Array.isArray(sec.blocks) ? sec.blocks : [];
        const first = blocks[0] || null;
        const t = String(first?.type || "");

        if (t === "home_hero") {
          const heroModel = {
            kicker: first.kicker || "",
            title: first.title || "",
            sub: first.sub || "",
            cta_text: first.cta_text || "",
            cta_href: first.cta_href || "",
            background_url: first.background_url || "",
          };
          return (
            <HeaderHero key={sec.id} model={heroModel} loading={loading} />
          );
        }

        if (t === "home_join") {
          const joinModel = {
            eyebrow: first.eyebrow || "",
            title: first.title || "",
            sub: first.sub || "",
            cta_text: first.cta_text || "",
            cta_href: first.cta_href || "",
          };
          return <JoinStrip key={sec.id} model={joinModel} />;
        }

        if (t === "featured_live") {
          if (first.show === false) return null;
          return <FeaturedHighlight key={sec.id} />;
        }

        if (t === "latest_teaching") {
          if (first.show === false) return null;
          return <LatestTeaching key={sec.id} />;
        }

        if (t === "home_cta") {
          const ctaModel = {
            title: first.title || "",
            sub: first.sub || "",
            cta_text: first.cta_text || "",
            cta_href: first.cta_href || "",
          };
          return (
            <WatchMoreCTA key={sec.id} model={ctaModel} loading={loading} />
          );
        }

        if (t === "home_about") {
          const aboutModel = {
            name: first.name || "",
            text: first.text || "",
            avatar_url: first.avatar_url || "",
          };
          return (
            <AboutSection key={sec.id} model={aboutModel} loading={loading} />
          );
        }

        return <BuilderSection key={sec.id} sec={sec} />;
      })}
    </>
  );
}

/* ---------------------------------------------------------
   1) HEADER + HERO
--------------------------------------------------------- */
function HeaderHero({ model, loading }) {
  const m = model || HOME_DEFAULTS.hero;

  const bg =
    absUrl(m.background_url) ||
    (m.background_url ? m.background_url : null) ||
    HomeBanner;

  return (
    <section className="hero-section" style={{ backgroundImage: `url(${bg})` }}>
      <div className="hero-overlay" />

      <div className="hero-content">
        <div className="hero-kicker">{m.kicker || ""}</div>

        <h1 className="hero-title">{m.title || ""}</h1>

        <p className="hero-sub">{m.sub || ""}</p>

        <Link className="hero-cta" to={m.cta_href || "/catalog"}>
          {m.cta_text || "Start Watching"}
        </Link>

        {/* keeps layout stable; only shows when truly loading */}
        {loading ? (
          <div style={{ marginTop: 12, opacity: 0.85 }}>
            <CircularSpinner size={28} label="Loading home content…" />
          </div>
        ) : null}
      </div>
    </section>
  );
}

