/* ---------------------------------------------------------
   7) EXTRA SECTIONS (Builder)
   - Reflects AdminPageEditor: layout/theme/styles/html/left_html/right_html
   - Keeps your existing layout intact by using lightweight inline styling
--------------------------------------------------------- */
function ExtraSections({ sections, loading }) {
  const list = useMemo(() => {
    const arr = Array.isArray(sections) ? sections : [];
    return arr.map(ensureSectionShape).filter((s) => {
      const hasContent =
        String(s.html || "").trim() ||
        String(s.left_html || "").trim() ||
        String(s.right_html || "").trim() ||
        (Array.isArray(s.blocks) && s.blocks.length);
      // Allow title-only sections if show_title is true
      const hasTitle = !!String(s.title || "").trim() && !!s.styles?.show_title;
      return hasContent || hasTitle;
    });
  }, [sections]);

  if (!list.length) return null;

  return (
    <section style={{ paddingBottom: 10 }}>
      {loading ? null : null}

      {list.map((sec) => (
        <BuilderSection key={sec.id} sec={sec} />
      ))}
    </section>
  );
}

function renderBlocks(sec, st) {
  const blocks = Array.isArray(sec.blocks) ? sec.blocks : [];
  if (!blocks.length) return null;

  return (
    <div
      className="brtv-blocks"
      style={{
        display: "grid",
        gap: clampNum(
          String(st.content_gap || "").trim()
            ? Number(String(st.content_gap).replace(/[^0-9.]/g, "")) || 18
            : 18,
          0,
          60,
        ),
        fontSize: String(st.font_size || "").trim() || undefined,
        lineHeight: String(st.line_height || "").trim() || undefined,
      }}
    >
      {blocks.map((b) => {
        const type = String(b.type || "richtext");

        // hero / banner
        if (type === "hero") {
          const bg = absUrl(b.bg_url || "");
          const img = absUrl(b.image_url || "");
          const fit = b.bg_fit || "cover";
          const bpos = b.bg_pos || "center";
          const height = Math.max(180, Number(b.height || 420));
          const maxW = String(b.max_width || "1120px").trim() || "1120px";
          const overlay = Math.max(
            0,
            Math.min(0.85, Number(b.overlay ?? 0.35)),
          );
          const align = b.align || "left";
          const vAlign = b.v_align || "center";
          const imgPos = b.img_pos || "right";
          const fullBleed = !!b.full_bleed;

          const justifyContent =
            align === "center"
              ? "center"
              : align === "right"
                ? "flex-end"
                : "flex-start";
          const alignItems =
            vAlign === "top"
              ? "flex-start"
              : vAlign === "bottom"
                ? "flex-end"
                : "center";

          const bgImage = bg
            ? `linear-gradient(rgba(0,0,0,${overlay}), rgba(0,0,0,${overlay})), url(${bg})`
            : `linear-gradient(rgba(0,0,0,${overlay}), rgba(0,0,0,${overlay}))`;

          return (
            <section
              key={b.id}
              className={`brtv-heroBlock ${fullBleed ? "is-bleed" : ""}`}
              style={{
                minHeight: height,
                backgroundImage: bgImage,
                backgroundSize: fit,
                backgroundPosition: bpos,
              }}
            >
              <div
                className="brtv-heroInner"
                style={{ maxWidth: fullBleed ? "1400px" : maxW }}
              >
                <div
                  className="brtv-heroRow"
                  style={{
                    justifyContent,
                    alignItems,
                    flexDirection: imgPos === "left" ? "row-reverse" : "row",
                  }}
                >
                  <div
                    className="brtv-heroContent"
                    style={{ textAlign: align }}
                  >
                    {!!String(b.title || "").trim() && (
                      <h2 className="brtv-heroTitle">{b.title}</h2>
                    )}
                    {!!String(b.text || "").trim() && (
                      <p className="brtv-heroText">{b.text}</p>
                    )}
                    {!!String(b.button_text || "").trim() && (
                      <a className="brtv-heroBtn" href={b.button_href || "#"}>
                        {b.button_text}
                      </a>
                    )}
                  </div>

                  {imgPos !== "none" && img ? (
                    <div className="brtv-heroMedia">
                      <img
                        src={img}
                        alt={b.image_alt || ""}
                        className="brtv-heroImg"
                      />
                    </div>
                  ) : null}
                </div>
              </div>
            </section>
          );
        }

        if (type === "grid") {
          const cols = Math.max(1, Math.min(6, Number(b.cols) || 3));
          const gap = Math.max(0, Number(b.gap) || 12);
          const items = Array.isArray(b.items) ? b.items : [];
          return (
            <div
              key={b.id}
              className="brtv-grid"
              style={{
                display: "grid",
                gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
                gap,
              }}
            >
              {items.map((it) => (
                <div key={it.id || `${b.id}-it`} className="brtv-gridItem">
                  {String(it.image_url || "").trim() ? (
                    <div className="brtv-gridImgWrap">
                      <img
                        alt=""
                        src={absUrl(it.image_url) || it.image_url}
                        className="brtv-gridImg"
                      />
                    </div>
                  ) : null}
                  {String(it.title || "").trim() ? (
                    <div className="brtv-gridTitle">{it.title}</div>
                  ) : null}
                  {String(it.text || "").trim() ? (
                    <div className="brtv-gridText">{it.text}</div>
                  ) : null}
                </div>
              ))}
            </div>
          );
        }

        if (type === "gallery") {
          const cols = Math.max(2, Math.min(8, Number(b.cols) || 4));
          const gap = Math.max(0, Number(b.gap) || 10);
          const images = Array.isArray(b.images) ? b.images : [];
          return (
            <div
              key={b.id}
              className="brtv-gallery"
              style={{
                display: "grid",
                gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
                gap,
              }}
            >
              {images.map((im) => (
                <a
                  key={im.id || `${b.id}-im`}
                  className="brtv-galleryItem"
                  href={absUrl(im.src) || im.src}
                  target="_blank"
                  rel="noreferrer"
                  title={im.alt || ""}
                >
                  <img alt={im.alt || ""} src={absUrl(im.src) || im.src} />
                </a>
              ))}
            </div>
          );
        }

        // richtext (default)
        return (
          <div
            key={b.id}
            className="brtv-richtext"
            dangerouslySetInnerHTML={safeHtml(String(b.html || ""))}
          />
        );
      })}
    </div>
  );
}

function BuilderSection({ sec }) {
  const st = sec.styles || defaultSectionStyle(sec.theme);
  const t = themeDefaults(sec.theme);

  // Layout mapping (kept minimal so your CSS doesn’t get disrupted)
  const isFull = sec.layout === "full";
  const isHighlight = sec.layout === "highlight";
  const isTwo = sec.layout === "two_columns";
  const hasBlocks = Array.isArray(sec.blocks) && sec.blocks.length > 0;

  const maxW = String(st.max_width || "").trim();
  const wrapMaxWidth = maxW || (isFull ? "100%" : "1100px");

  const pad = st.padding || (isFull ? "48px 0" : "22px 18px");
  const mg = st.margin || (isFull ? "0" : "18px auto");

  const radius = clampNum(st.radius ?? 14, 0, 60);

  const bgColor =
    String(st.bg_color || "").trim() ||
    (isHighlight ? "rgba(154, 92, 255, 0.12)" : t.bg);

  const borderColor = String(st.border_color || "").trim() || t.border;

  const textColor = String(st.text_color || "").trim() || t.text;

  const titleColor = String(st.title_color || "").trim() || textColor;

  const overlay = Math.max(0, Math.min(0.9, Number(st.overlay ?? 0) || 0));

  const bgImg =
    absUrl(st.bg_image_url) || (st.bg_image_url ? st.bg_image_url : null);

  const bgPosition = String(st.bg_image_pos || "center");
  const bgFit = String(st.bg_image_fit || "cover");

  const borderW = String(st.border_width || "").trim();
  const overlayOpacityNumRaw =
    String(st.overlay_opacity ?? "").trim() === ""
      ? null
      : Number(st.overlay_opacity);
  const overlayOpacityNum = Number.isFinite(overlayOpacityNumRaw)
    ? Math.max(0, Math.min(0.9, overlayOpacityNumRaw))
    : overlay;

  const overlayColor = String(st.overlay_color || "").trim();
  const overlayLayer = overlayColor
    ? `linear-gradient(${overlayColor}, ${overlayColor})`
    : `linear-gradient(rgba(0,0,0,${overlayOpacityNum}), rgba(0,0,0,${overlayOpacityNum}))`;

  const contentGap = String(st.content_gap || "").trim()
    ? String(st.content_gap).trim()
    : "12px";

  const outerStyle = {
    margin: mg,
    maxWidth: wrapMaxWidth,
  };

  const innerStyle = {
    position: "relative",
    padding: pad,
    minHeight: String(st.min_height || "").trim() || undefined,
    height: String(st.height || "").trim() || undefined,
    borderRadius: radius,
    color: textColor,
    background: bgImg ? `${overlayLayer}, url(${bgImg})` : bgColor,
    backgroundSize: bgImg ? bgFit : undefined,
    backgroundPosition: bgImg ? bgPosition : undefined,
    backgroundRepeat: bgImg ? "no-repeat" : undefined,
    border: `${borderW || "1px"} solid ${borderColor}`,
    boxShadow: shadowCss(st.shadow),
    textAlign: String(st.align || "left"),
    overflow: "hidden",
    // don’t force width changes; let Home.css do the layout
  };

  const contentMax = isFull ? "1100px" : "100%";

  const Tag = String(st.title_tag || "h3");

  const titleStyle = {
    color: titleColor,
    fontSize: clampNum(st.title_size ?? 22, 10, 64),
    fontWeight: clampNum(st.title_weight ?? 800, 200, 900),
    margin: 0,
    marginBottom: contentGap,
    letterSpacing: -0.2,
  };

  const imgRadius = clampNum(st.img_radius ?? 12, 0, 60);
  const imgShadow =
    st.img_shadow === "soft" ? "0 14px 50px rgba(0,0,0,0.45)" : "none";

  const scopedCss = `
    #sec-${sec.id} img {
      border-radius: ${imgRadius}px;
      box-shadow: ${imgShadow};
    }
    #sec-${sec.id} a { color: inherit; }
  `;

  return (
    <div style={outerStyle}>
      <div id={`sec-${sec.id}`} style={innerStyle}>
        <style>{scopedCss}</style>

        <div
          style={{
            maxWidth: contentMax,
            margin: "0 auto",
            fontSize: String(st.font_size || "").trim() || undefined,
            lineHeight: String(st.line_height || "").trim() || undefined,
          }}
        >
          {st.show_title !== false && String(sec.title || "").trim() ? (
            <Tag style={titleStyle}>{sec.title}</Tag>
          ) : null}

          {hasBlocks ? (
            renderBlocks(sec, st)
          ) : isTwo ? (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 18,
                alignItems: "start",
              }}
            >
              <div
                style={{ minWidth: 0 }}
                dangerouslySetInnerHTML={safeHtml(sec.left_html || "")}
              />
              <div
                style={{ minWidth: 0 }}
                dangerouslySetInnerHTML={safeHtml(sec.right_html || "")}
              />
            </div>
          ) : (
            <div dangerouslySetInnerHTML={safeHtml(sec.html || "")} />
          )}
        </div>
      </div>
    </div>
  );
}

function Spacer() {
  return <div className="spacer" />;
}
